    void 
    EnergyStartStopLevelSequencePluginSupport_print_data(
        const EnergyStartStopLevelSequence *sample,
        const char *desc,
        unsigned int indent_level)
    {

        RTICdrType_printIndent(indent_level);

        if (desc != NULL) {
            RTILogParamString_printPlain("%s:\n", desc);
        } else {
            RTILogParamString_printPlain("\n");
        }

        if (sample == NULL) {
            RTILogParamString_printPlain("NULL\n");
            return;
        }

        if (tms::EnergyStartStopLevelSeq_get_contiguous_bufferI(sample) != NULL) {
            RTICdrType_printArray(
                tms::EnergyStartStopLevelSeq_get_contiguous_bufferI(sample), 
                (RTICdrUnsignedLong) tms::EnergyStartStopLevelSeq_get_length(sample),
                sizeof(tms::EnergyStartStopLevel),
                (RTICdrTypePrintFunction)tms::EnergyStartStopLevelPluginSupport_print_data,
                "", indent_level + 1);
        } else {
            RTICdrType_printPointerArray(
                tms::EnergyStartStopLevelSeq_get_discontiguous_bufferI(sample), 
                (RTICdrUnsignedLong) tms::EnergyStartStopLevelSeq_get_length(sample),
                (RTICdrTypePrintFunction)tms::EnergyStartStopLevelPluginSupport_print_data,
                "", indent_level + 1);
        }

    }

