    void 
    SynchronousMachineCoefficientsPluginSupport_print_data(
        const SynchronousMachineCoefficients *sample,
        const char *desc,
        unsigned int indent_level)
    {

        RTICdrType_printIndent(indent_level);

        if (desc != NULL) {
            RTILogParamString_printPlain("%s:\n", desc);
        } else {
            RTILogParamString_printPlain("\n");
        }

        if (sample == NULL) {
            RTILogParamString_printPlain("NULL\n");
            return;
        }

        RTICdrType_printFloat(
            &sample->statorResistancePerPhase, "statorResistancePerPhase", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->statorLeakageReactance, "statorLeakageReactance", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->zeroSequenceReactance, "zeroSequenceReactance", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->negativeSequenceReactance, "negativeSequenceReactance", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->zeroSequenceResistance, "zeroSequenceResistance", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->negativeSequenceResistance, "negativeSequenceResistance", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->directAxisSynchronousReactance, "directAxisSynchronousReactance", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->directAxisTransientReactance, "directAxisTransientReactance", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->directAxisSubtransientReactance, "directAxisSubtransientReactance", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->quadratureAxisSynchronousReactance, "quadratureAxisSynchronousReactance", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->quadratureAxisTransientReactance, "quadratureAxisTransientReactance", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->quadratureAxisSubtransientReactance, "quadratureAxisSubtransientReactance", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->directAxisTransientShortCircuitTimeConstant, "directAxisTransientShortCircuitTimeConstant", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->directAxisSubtransientShortCircuitTimeConstant, "directAxisSubtransientShortCircuitTimeConstant", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->directAxisTransientOpenCircuitTimeConstant, "directAxisTransientOpenCircuitTimeConstant", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->directAxisSubtransientOpenCircuitTimeConstant, "directAxisSubtransientOpenCircuitTimeConstant", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->quadratureAxisTransientShortCircuitTimeConstant, "quadratureAxisTransientShortCircuitTimeConstant", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->quadratureAxisSubtransientShortCircuitTimeConstant, "quadratureAxisSubtransientShortCircuitTimeConstant", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->quadratureAxisTransientOpenCircuitTimeConstant, "quadratureAxisTransientOpenCircuitTimeConstant", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->quadratureAxisSubtransientOpenCircuitTimeConstant, "quadratureAxisSubtransientOpenCircuitTimeConstant", indent_level + 1);    

    }

