    void 
    GeneratorInfoPluginSupport_print_data(
        const GeneratorInfo *sample,
        const char *desc,
        unsigned int indent_level)
    {

        RTICdrType_printIndent(indent_level);

        if (desc != NULL) {
            RTILogParamString_printPlain("%s:\n", desc);
        } else {
            RTILogParamString_printPlain("\n");
        }

        if (sample == NULL) {
            RTILogParamString_printPlain("NULL\n");
            return;
        }

        RTICdrType_printFloat(
            &sample->minFieldCurrent, "minFieldCurrent", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->maxFieldCurrent, "maxFieldCurrent", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->maxStatorTemperature, "maxStatorTemperature", indent_level + 1);    

    }

