    /* -----------------------------------------------------------------------------
    Support functions:
    * -------------------------------------------------------------------------- */

    EngineInfo*
    EngineInfoPluginSupport_create_data_w_params(
        const struct DDS_TypeAllocationParams_t * alloc_params) 
    {
        EngineInfo *sample = NULL;

        if (alloc_params == NULL) {
            return NULL;
        } else if(!alloc_params->allocate_memory) {
            RTICdrLog_exception(&RTI_CDR_LOG_TYPE_OBJECT_NOT_ASSIGNABLE_ss,
            "alloc_params->allocate_memory","false");
            return NULL;
        }

        sample = new (std::nothrow) EngineInfo();
        if (sample == NULL) {
            return NULL;
        }

        if (!tms::EngineInfo_initialize_w_params(sample,alloc_params)) {
            struct DDS_TypeDeallocationParams_t deallocParams =
            DDS_TYPE_DEALLOCATION_PARAMS_DEFAULT;
            deallocParams.delete_pointers = alloc_params->allocate_pointers;
            deallocParams.delete_optional_members = alloc_params->allocate_pointers;
            /* Coverity reports a possible uninit_use_in_call that will happen if the
            allocation fails. But if the allocation fails then sample == null and
            the method will return before reach this point.*/
            /* coverity[uninit_use_in_call : FALSE] */
            tms::EngineInfo_finalize_w_params(sample, &deallocParams);
            delete  sample;
            sample=NULL;
        }
        return sample;
    } 

    EngineInfo *
    EngineInfoPluginSupport_create_data_ex(RTIBool allocate_pointers) 
    {
        EngineInfo *sample = NULL;

        sample = new (std::nothrow) EngineInfo();

        if(sample == NULL) {
            return NULL;
        }

        if (!tms::EngineInfo_initialize_ex(sample,allocate_pointers, RTI_TRUE)) {
            /* Coverity reports a possible uninit_use_in_call that will happen if the
            new fails. But if new fails then sample == null and the method will
            return before reach this point. */
            /* coverity[uninit_use_in_call : FALSE] */
            tms::EngineInfo_finalize_ex(sample, RTI_TRUE);
            delete  sample;
            sample=NULL;
        }

        return sample;
    }

    EngineInfo *
    EngineInfoPluginSupport_create_data(void)
    {
        return tms::EngineInfoPluginSupport_create_data_ex(RTI_TRUE);
    }

    void 
    EngineInfoPluginSupport_destroy_data_w_params(
        EngineInfo *sample,
        const struct DDS_TypeDeallocationParams_t * dealloc_params) {
        tms::EngineInfo_finalize_w_params(sample,dealloc_params);

        delete  sample;
    }

