        RTICdrType_printBoolean(
            &sample->supportsConstantPower, "supportsConstantPower", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->minRealPower, "minRealPower", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->maxRealPower, "maxRealPower", indent_level + 1);    

        tms::Curve2DPluginSupport_print_data(
            (const tms::Curve2D*) sample->maxOverloadRealPower, "maxOverloadRealPower", indent_level + 1);

        RTICdrType_printFloat(
            &sample->minReactivePower, "minReactivePower", indent_level + 1);    

