    void 
    PowerHardwareInfoPluginSupport_print_data(
        const PowerHardwareInfo *sample,
        const char *desc,
        unsigned int indent_level)
    {

        RTICdrType_printIndent(indent_level);

        if (desc != NULL) {
            RTILogParamString_printPlain("%s:\n", desc);
        } else {
            RTILogParamString_printPlain("\n");
        }

        if (sample == NULL) {
            RTILogParamString_printPlain("NULL\n");
            return;
        }

        tms::EngineInfoPluginSupport_print_data(
            (const tms::EngineInfo*) sample->engine, "engine", indent_level + 1);

        tms::FuelInfoPluginSupport_print_data(
            (const tms::FuelInfo*) sample->fuel, "fuel", indent_level + 1);

        tms::GeneratorInfoPluginSupport_print_data(
            (const tms::GeneratorInfo*) sample->generator, "generator", indent_level + 1);

        tms::EnergyStorageInfoPluginSupport_print_data(
            (const tms::EnergyStorageInfo*) sample->energyStorage, "energyStorage", indent_level + 1);

        tms::PowerElectronicsInfoPluginSupport_print_data(
            (const tms::PowerElectronicsInfo*) sample->powerElectronics, "powerElectronics", indent_level + 1);

        tms::ThermalInfoPluginSupport_print_data(
            (const tms::ThermalInfo*) sample->thermal, "thermal", indent_level + 1);

        tms::SynchronousMachineCoefficientsPluginSupport_print_data(
            (const tms::SynchronousMachineCoefficients*) sample->synchronousMachineModel, "synchronousMachineModel", indent_level + 1);

    }

