    void 
    PowerHardwareUpdatePluginSupport_print_data(
        const PowerHardwareUpdate *sample,
        const char *desc,
        unsigned int indent_level)
    {

        RTICdrType_printIndent(indent_level);

        if (desc != NULL) {
            RTILogParamString_printPlain("%s:\n", desc);
        } else {
            RTILogParamString_printPlain("\n");
        }

        if (sample == NULL) {
            RTILogParamString_printPlain("NULL\n");
            return;
        }

        if (sample->deviceId==NULL) {
            RTICdrType_printString(
                NULL,"deviceId", indent_level + 1);
        } else {
            RTICdrType_printString(
                sample->deviceId,"deviceId", indent_level + 1);    
        }

        tms::ClockMonotonicPluginSupport_print_data(
            (const tms::ClockMonotonic*) &sample->timestamp, "timestamp", indent_level + 1);

        tms::EngineStatePluginSupport_print_data(
            (const tms::EngineState*) sample->engine, "engine", indent_level + 1);

        tms::FuelStatePluginSupport_print_data(
            (const tms::FuelState*) sample->fuel, "fuel", indent_level + 1);

        tms::GeneratorStatePluginSupport_print_data(
            (const tms::GeneratorState*) sample->generator, "generator", indent_level + 1);

        tms::EnergyStorageStatePluginSupport_print_data(
            (const tms::EnergyStorageState*) sample->energyStorage, "energyStorage", indent_level + 1);

        tms::PowerElectronicsStatePluginSupport_print_data(
            (const tms::PowerElectronicsState*) sample->powerElectronics, "powerElectronics", indent_level + 1);

        tms::ThermalStatePluginSupport_print_data(
            (const tms::ThermalState*) sample->thermal, "thermal", indent_level + 1);

    }

