    RTIBool 
    PowerHardwareUpdatePlugin_instance_to_key(
        PRESTypePluginEndpointData endpoint_data,
        PowerHardwareUpdateKeyHolder *dst, 
        const PowerHardwareUpdate *src)
    {
        if (endpoint_data) {} /* To avoid warnings */   

        if (!RTICdrType_copyStringEx (
            &dst->deviceId
            ,
            src->deviceId, 
            ((tms::Identity_MAXLEN)) + 1,
            RTI_FALSE)){
            return RTI_FALSE;
        }
        return RTI_TRUE;
    }

    RTIBool 
    PowerHardwareUpdatePlugin_key_to_instance(
        PRESTypePluginEndpointData endpoint_data,
        PowerHardwareUpdate *dst, const
        PowerHardwareUpdateKeyHolder *src)
    {
        if (endpoint_data) {} /* To avoid warnings */   
        if (!RTICdrType_copyStringEx (
            &dst->deviceId
            ,
            src->deviceId, 
            ((tms::Identity_MAXLEN)) + 1,
            RTI_FALSE)){
            return RTI_FALSE;
        }
        return RTI_TRUE;
    }

    RTIBool 
    PowerHardwareUpdatePlugin_serialized_sample_to_keyhash(
        PRESTypePluginEndpointData endpoint_data,
        struct RTICdrStream *stream, 
        DDS_KeyHash_t *keyhash,
        RTIBool deserialize_encapsulation,
        void *endpoint_plugin_qos) 
    {   
        PowerHardwareUpdate * sample = NULL;
        sample = (PowerHardwareUpdate *)
        PRESTypePluginDefaultEndpointData_getTempSample(endpoint_data);
        if (sample == NULL) {
            return RTI_FALSE;
        }

        if (!PRESTypePlugin_interpretedSerializedSampleToKey(
            endpoint_data,
            sample,
            stream, 
            deserialize_encapsulation, 
            RTI_TRUE,
            endpoint_plugin_qos)) {
            return RTI_FALSE;
        }
        if (!PRESTypePlugin_interpretedInstanceToKeyHash(
            endpoint_data, 
            keyhash, 
            sample,
            RTICdrStream_getEncapsulationKind(stream))) {
            return RTI_FALSE;
        }
        return RTI_TRUE;
    }

