    DiagnosticTroubleCodePluginSupport_copy_data(
        DiagnosticTroubleCode *dst,
        const DiagnosticTroubleCode *src)
    {
        return tms::DiagnosticTroubleCode_copy(dst,(const DiagnosticTroubleCode*) src);
    }

    void 
    DiagnosticTroubleCodePluginSupport_print_data(
        const DiagnosticTroubleCode *sample,
        const char *desc,
        unsigned int indent_level)
    {

        RTICdrType_printIndent(indent_level);

        if (desc != NULL) {
            RTILogParamString_printPlain("%s:\n", desc);
        } else {
            RTILogParamString_printPlain("\n");
        }

        if (sample == NULL) {
            RTILogParamString_printPlain("NULL\n");
            return;
        }

        RTICdrType_printLong(
            sample->portNumber, "portNumber", indent_level + 1);    

        RTICdrType_printUnsignedLong(
            &sample->suspectParameter, "suspectParameter", indent_level + 1);    

        tms::FailureModeIndicatorPluginSupport_print_data(
            (const tms::FailureModeIndicator*) &sample->failureMode, "failureMode", indent_level + 1);

        RTICdrType_printUnsignedLong(
            &sample->occurrenceCount, "occurrenceCount", indent_level + 1);    

        tms::ClockMonotonicPluginSupport_print_data(
            (const tms::ClockMonotonic*) &sample->timeRaised, "timeRaised", indent_level + 1);

        tms::DtcSeverityPluginSupport_print_data(
            (const tms::DtcSeverity*) &sample->severity, "severity", indent_level + 1);

        tms::ClockMonotonicPluginSupport_print_data(
            (const tms::ClockMonotonic*) sample->estimateTime, "estimateTime", indent_level + 1);

        tms::DtcSeverityPluginSupport_print_data(
            (const tms::DtcSeverity*) sample->estimateSeverity, "estimateSeverity", indent_level + 1);

        if (sample->hint==NULL) {
            RTICdrType_printString(
                NULL,"hint", indent_level + 1);
        } else {
            RTICdrType_printString(
                sample->hint,"hint", indent_level + 1);    
        }

    }

