    void 
    ClockStatePluginSupport_print_data(
        const ClockState *sample,
        const char *desc,
        unsigned int indent_level)
    {

        RTICdrType_printIndent(indent_level);

        if (desc != NULL) {
            RTILogParamString_printPlain("%s:\n", desc);
        } else {
            RTILogParamString_printPlain("\n");
        }

        if (sample == NULL) {
            RTILogParamString_printPlain("NULL\n");
            return;
        }

        if (sample->deviceId==NULL) {
            RTICdrType_printString(
                NULL,"deviceId", indent_level + 1);
        } else {
            RTICdrType_printString(
                sample->deviceId,"deviceId", indent_level + 1);    
        }

        tms::ClockMonotonicPluginSupport_print_data(
            (const tms::ClockMonotonic*) &sample->monotonic, "monotonic", indent_level + 1);

        tms::ClockMonotonicPersistenceTypePluginSupport_print_data(
            (const tms::ClockMonotonicPersistenceType*) &sample->monotonicPersistence, "monotonicPersistence", indent_level + 1);

        tms::ClockRealtimePluginSupport_print_data(
            (const tms::ClockRealtime*) &sample->realtime, "realtime", indent_level + 1);

        tms::ClockSourcePluginSupport_print_data(
            (const tms::ClockSource*) &sample->realtimeSource, "realtimeSource", indent_level + 1);

        tms::ClockRealtimePluginSupport_print_data(
            (const tms::ClockRealtime*) &sample->realtimeSetTime, "realtimeSetTime", indent_level + 1);

    }

