    void 
    PowerPortInfoPluginSupport_print_data(
        const PowerPortInfo *sample,
        const char *desc,
        unsigned int indent_level)
    {

        RTICdrType_printIndent(indent_level);

        if (desc != NULL) {
            RTILogParamString_printPlain("%s:\n", desc);
        } else {
            RTILogParamString_printPlain("\n");
        }

        if (sample == NULL) {
            RTILogParamString_printPlain("NULL\n");
            return;
        }

        RTICdrType_printLong(
            &sample->portNumber, "portNumber", indent_level + 1);    

        tms::CircuitWiringPluginSupport_print_data(
            (const tms::CircuitWiring*) &sample->wiring, "wiring", indent_level + 1);

        tms::PowerPortDirectionalityPluginSupport_print_data(
            (const tms::PowerPortDirectionality*) &sample->directionality, "directionality", indent_level + 1);

        RTICdrType_printBoolean(
            &sample->hasSwitch, "hasSwitch", indent_level + 1);    

        RTICdrType_printBoolean(
            &sample->hasExternalMeter, "hasExternalMeter", indent_level + 1);    

        RTICdrType_printBoolean(
            &sample->hasInternalMeter, "hasInternalMeter", indent_level + 1);    

        RTICdrType_printBoolean(
            &sample->hasSummaryMeasurementUpdate, "hasSummaryMeasurementUpdate", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->minAmperage, "minAmperage", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->maxAmperage, "maxAmperage", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->shortCircuitAmperage, "shortCircuitAmperage", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->minVoltage, "minVoltage", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->maxVoltage, "maxVoltage", indent_level + 1);    

        RTICdrType_printFloat(
            sample->minFrequency, "minFrequency", indent_level + 1);    

        RTICdrType_printFloat(
            sample->maxFrequency, "maxFrequency", indent_level + 1);    

        tms::PowerConnectorInfoPluginSupport_print_data(
            (const tms::PowerConnectorInfo*) &sample->connectorInfo, "connectorInfo", indent_level + 1);

        tms::PowerSwitchInfoPluginSupport_print_data(
            (const tms::PowerSwitchInfo*) sample->switchInfo, "switchInfo", indent_level + 1);

    }

