    void 
    PowerSwitchStatusPluginSupport_print_data(
        const PowerSwitchStatus *sample,
        const char *desc,
        unsigned int indent_level)
    {

        RTICdrType_printIndent(indent_level);

        if (desc != NULL) {
            RTILogParamString_printPlain("%s:\n", desc);
        } else {
            RTILogParamString_printPlain("\n");
        }

        if (sample == NULL) {
            RTILogParamString_printPlain("NULL\n");
            return;
        }

        tms::CircuitContinuityPluginSupport_print_data(
            (const tms::CircuitContinuity*) &sample->presentContinuity, "presentContinuity", indent_level + 1);

        tms::CircuitContinuityPluginSupport_print_data(
            (const tms::CircuitContinuity*) &sample->futureContinuity, "futureContinuity", indent_level + 1);

        RTICdrType_printBoolean(
            &sample->requestLock, "requestLock", indent_level + 1);    

        tms::PowerSwitchReasonPluginSupport_print_data(
            (const tms::PowerSwitchReason*) &sample->presentContinuityReason, "presentContinuityReason", indent_level + 1);

        if (sample->presentContinuityActor==NULL) {
            RTICdrType_printString(
                NULL,"presentContinuityActor", indent_level + 1);
        } else {
            RTICdrType_printString(
                sample->presentContinuityActor,"presentContinuityActor", indent_level + 1);    
        }

        tms::PowerSwitchTransitionCodePluginSupport_print_data(
            (const tms::PowerSwitchTransitionCode*) &sample->futureContinuityReason, "futureContinuityReason", indent_level + 1);

    }

