    void 
    GroundingInfoPluginSupport_print_data(
        const GroundingInfo *sample,
        const char *desc,
        unsigned int indent_level)
    {

        RTICdrType_printIndent(indent_level);

        if (desc != NULL) {
            RTILogParamString_printPlain("%s:\n", desc);
        } else {
            RTILogParamString_printPlain("\n");
        }

        if (sample == NULL) {
            RTILogParamString_printPlain("NULL\n");
            return;
        }

        RTICdrType_printLong(
            &sample->groundNumber, "groundNumber", indent_level + 1);    

        tms::GroundingDesignTypePluginSupport_print_data(
            (const tms::GroundingDesignType*) &sample->groundType, "groundType", indent_level + 1);

        tms::PowerPortNumberSequencePluginSupport_print_data(
            (const tms::PowerPortNumberSequence*) &sample->protectedPorts, "protectedPorts", indent_level + 1);

        tms::PowerSwitchFeatureSequencePluginSupport_print_data(
            (const tms::PowerSwitchFeatureSequence*) &sample->controlSwitchFeatures, "controlSwitchFeatures", indent_level + 1);

        tms::PowerSwitchFeatureSequencePluginSupport_print_data(
            (const tms::PowerSwitchFeatureSequence*) &sample->pulseSwitchFeatures, "pulseSwitchFeatures", indent_level + 1);

    }

