    void 
    PowerPortStatusPluginSupport_print_data(
        const PowerPortStatus *sample,
        const char *desc,
        unsigned int indent_level)
    {

        RTICdrType_printIndent(indent_level);

        if (desc != NULL) {
            RTILogParamString_printPlain("%s:\n", desc);
        } else {
            RTILogParamString_printPlain("\n");
        }

        if (sample == NULL) {
            RTILogParamString_printPlain("NULL\n");
            return;
        }

        RTICdrType_printLong(
            &sample->portNumber, "portNumber", indent_level + 1);    

        tms::CableSenseStatusPluginSupport_print_data(
            (const tms::CableSenseStatus*) &sample->cableStatus, "cableStatus", indent_level + 1);

        if (sample->cableId==NULL) {
            RTICdrType_printString(
                NULL,"cableId", indent_level + 1);
        } else {
            RTICdrType_printString(
                sample->cableId,"cableId", indent_level + 1);    
        }

        tms::PowerPortIdPluginSupport_print_data(
            (const tms::PowerPortId*) sample->connection, "connection", indent_level + 1);

        tms::PowerSwitchStatusPluginSupport_print_data(
            (const tms::PowerSwitchStatus*) sample->switchStatus, "switchStatus", indent_level + 1);

    }

