    void 
    ActiveDiagnosticStatePluginSupport_print_data(
        const ActiveDiagnosticState *sample,
        const char *desc,
        unsigned int indent_level)
    {

        RTICdrType_printIndent(indent_level);

        if (desc != NULL) {
            RTILogParamString_printPlain("%s:\n", desc);
        } else {
            RTILogParamString_printPlain("\n");
        }

        if (sample == NULL) {
            RTILogParamString_printPlain("NULL\n");
            return;
        }

        if (sample->deviceId==NULL) {
            RTICdrType_printString(
                NULL,"deviceId", indent_level + 1);
        } else {
            RTICdrType_printString(
                sample->deviceId,"deviceId", indent_level + 1);    
        }

        tms::DiagnosticTroubleCodeSequencePluginSupport_print_data(
            (const tms::DiagnosticTroubleCodeSequence*) &sample->codes, "codes", indent_level + 1);

        RTICdrType_printUnsignedLong(
            &sample->overflow, "overflow", indent_level + 1);    

    }

