    void 
    AuthorizationToEnergizeRequestPluginSupport_print_data(
        const AuthorizationToEnergizeRequest *sample,
        const char *desc,
        unsigned int indent_level)
    {

        RTICdrType_printIndent(indent_level);

        if (desc != NULL) {
            RTILogParamString_printPlain("%s:\n", desc);
        } else {
            RTILogParamString_printPlain("\n");
        }

        if (sample == NULL) {
            RTILogParamString_printPlain("NULL\n");
            return;
        }

        tms::GridRequestPluginSupport_print_data(
            (const tms::GridRequest*) &sample->requestId, "requestId", indent_level + 1);

        RTICdrType_printUnsignedLongLong(
            &sample->sequenceId, "sequenceId", indent_level + 1);    

        if (sample->energizeRequestingDeviceId==NULL) {
            RTICdrType_printString(
                NULL,"energizeRequestingDeviceId", indent_level + 1);
        } else {
            RTICdrType_printString(
                sample->energizeRequestingDeviceId,"energizeRequestingDeviceId", indent_level + 1);    
        }

        RTICdrType_printUnsignedLongLong(
            &sample->energizeSequenceId, "energizeSequenceId", indent_level + 1);    

        tms::PowerPortNumberSequencePluginSupport_print_data(
            (const tms::PowerPortNumberSequence*) &sample->powerPorts, "powerPorts", indent_level + 1);

    }

