    void 
    AuthorizationToEnergizeReplyPluginSupport_print_data(
        const AuthorizationToEnergizeReply *sample,
        const char *desc,
        unsigned int indent_level)
    {

        RTICdrType_printIndent(indent_level);

        if (desc != NULL) {
            RTILogParamString_printPlain("%s:\n", desc);
        } else {
            RTILogParamString_printPlain("\n");
        }

        if (sample == NULL) {
            RTILogParamString_printPlain("NULL\n");
            return;
        }

        if (sample->deviceId==NULL) {
            RTICdrType_printString(
                NULL,"deviceId", indent_level + 1);
        } else {
            RTICdrType_printString(
                sample->deviceId,"deviceId", indent_level + 1);    
        }

        tms::GridRequestPluginSupport_print_data(
            (const tms::GridRequest*) &sample->relatedRequestId, "relatedRequestId", indent_level + 1);

        RTICdrType_printUnsignedLongLong(
            &sample->relatedSequenceId, "relatedSequenceId", indent_level + 1);    

        if (sample->energizeRequestingDeviceId==NULL) {
            RTICdrType_printString(
                NULL,"energizeRequestingDeviceId", indent_level + 1);
        } else {
            RTICdrType_printString(
                sample->energizeRequestingDeviceId,"energizeRequestingDeviceId", indent_level + 1);    
        }

        RTICdrType_printUnsignedLongLong(
            &sample->energizeSequenceId, "energizeSequenceId", indent_level + 1);    

        tms::PowerPortNumberSequencePluginSupport_print_data(
            (const tms::PowerPortNumberSequence*) &sample->powerPorts, "powerPorts", indent_level + 1);

        if (sample->userId==NULL) {
            RTICdrType_printString(
                NULL,"userId", indent_level + 1);
        } else {
            RTICdrType_printString(
                sample->userId,"userId", indent_level + 1);    
        }

        RTICdrType_printBoolean(
            &sample->accept, "accept", indent_level + 1);    

        RTICdrType_printBoolean(
            &sample->deny, "deny", indent_level + 1);    

        tms::ClockRealtimePluginSupport_print_data(
            (const tms::ClockRealtime*) &sample->timeOfReview, "timeOfReview", indent_level + 1);

    }

