    void 
    IdentityNicknameRequestPluginSupport_print_data(
        const IdentityNicknameRequest *sample,
        const char *desc,
        unsigned int indent_level)
    {

        RTICdrType_printIndent(indent_level);

        if (desc != NULL) {
            RTILogParamString_printPlain("%s:\n", desc);
        } else {
            RTILogParamString_printPlain("\n");
        }

        if (sample == NULL) {
            RTILogParamString_printPlain("NULL\n");
            return;
        }

        tms::DeviceRequestPluginSupport_print_data(
            (const tms::DeviceRequest*) &sample->requestId, "requestId", indent_level + 1);

        RTICdrType_printUnsignedLongLong(
            &sample->sequenceId, "sequenceId", indent_level + 1);    

        if (sample->nickname==NULL) {
            RTICdrType_printString(
                NULL,"nickname", indent_level + 1);
        } else {
            RTICdrType_printString(
                sample->nickname,"nickname", indent_level + 1);    
        }

    }

