    DeviceIconPluginSupport_destroy_data_w_params(
        DeviceIcon *sample,
        const struct DDS_TypeDeallocationParams_t * dealloc_params) {
        tms::DeviceIcon_finalize_w_params(sample,dealloc_params);

        delete  sample;
    }

