    void 
    DeviceIconPluginSupport_print_data(
        const DeviceIcon *sample,
        const char *desc,
        unsigned int indent_level)
    {

        RTICdrType_printIndent(indent_level);

        if (desc != NULL) {
            RTILogParamString_printPlain("%s:\n", desc);
        } else {
            RTILogParamString_printPlain("\n");
        }

        if (sample == NULL) {
            RTILogParamString_printPlain("NULL\n");
            return;
        }

        if (sample->deviceId==NULL) {
            RTICdrType_printString(
                NULL,"deviceId", indent_level + 1);
        } else {
            RTICdrType_printString(
                sample->deviceId,"deviceId", indent_level + 1);    
        }

        if (sample->mimeType==NULL) {
            RTICdrType_printString(
                NULL,"mimeType", indent_level + 1);
        } else {
            RTICdrType_printString(
                sample->mimeType,"mimeType", indent_level + 1);    
        }

        tms::OctetSequencePluginSupport_print_data(
            (const tms::OctetSequence*) &sample->data, "data", indent_level + 1);

    }

