    DeviceIconPluginSupport_create_key_ex(RTIBool allocate_pointers){
        DeviceIcon *key = NULL;

        key = new (std::nothrow) DeviceIconKeyHolder();

        tms::DeviceIcon_initialize_ex(key,allocate_pointers, RTI_TRUE);

        return key;
    }

