    void 
    DeviceIntentPluginSupport_print_data(
        const DeviceIntent *sample,
        const char *desc,
        unsigned int indent_level)
    {

        RTICdrType_printIndent(indent_level);

        if (desc != NULL) {
            RTILogParamString_printPlain("%s:\n", desc);
        } else {
            RTILogParamString_printPlain("\n");
        }

        if (sample == NULL) {
            RTILogParamString_printPlain("NULL\n");
            return;
        }

        if (sample->deviceId==NULL) {
            RTICdrType_printString(
                NULL,"deviceId", indent_level + 1);
        } else {
            RTICdrType_printString(
                sample->deviceId,"deviceId", indent_level + 1);    
        }

        RTICdrType_printBoolean(
            &sample->battleShort, "battleShort", indent_level + 1);    

        tms::OperatorPriorityPluginSupport_print_data(
            (const tms::OperatorPriority*) &sample->priority, "priority", indent_level + 1);

    }

