    ControlParameterStatePluginSupport_create_key_ex(RTIBool allocate_pointers){
        ControlParameterState *key = NULL;

        key = new (std::nothrow) ControlParameterStateKeyHolder();

        tms::ControlParameterState_initialize_ex(key,allocate_pointers, RTI_TRUE);

        return key;
    }

