    void 
    GroundingCircuitRequestPluginSupport_print_data(
        const GroundingCircuitRequest *sample,
        const char *desc,
        unsigned int indent_level)
    {

        RTICdrType_printIndent(indent_level);

        if (desc != NULL) {
            RTILogParamString_printPlain("%s:\n", desc);
        } else {
            RTILogParamString_printPlain("\n");
        }

        if (sample == NULL) {
            RTILogParamString_printPlain("NULL\n");
            return;
        }

        tms::DeviceConfigRequestPluginSupport_print_data(
            (const tms::DeviceConfigRequest*) &sample->requestId, "requestId", indent_level + 1);

        RTICdrType_printUnsignedLongLong(
            &sample->sequenceId, "sequenceId", indent_level + 1);    

        RTICdrType_printLong(
            &sample->groundNumber, "groundNumber", indent_level + 1);    

        tms::DesiredCircuitContinuityPluginSupport_print_data(
            (const tms::DesiredCircuitContinuity*) &sample->control, "control", indent_level + 1);

        tms::DesiredCircuitContinuityPluginSupport_print_data(
            (const tms::DesiredCircuitContinuity*) &sample->pulse, "pulse", indent_level + 1);

    }

