        if (!RTICdrType_copyStringEx (
            &dst->deviceId
            ,
            src->deviceId, 
            ((tms::Identity_MAXLEN)) + 1,
            RTI_FALSE)){
            return RTI_FALSE;
        }
        return RTI_TRUE;
