    void 
    LoadSharingIntentPluginSupport_print_data(
        const LoadSharingIntent *sample,
        const char *desc,
        unsigned int indent_level)
    {

        RTICdrType_printIndent(indent_level);

        if (desc != NULL) {
            RTILogParamString_printPlain("%s:\n", desc);
        } else {
            RTILogParamString_printPlain("\n");
        }

        if (sample == NULL) {
            RTILogParamString_printPlain("NULL\n");
            return;
        }

        RTICdrType_printFloat(
            &sample->increaseCapacityThreshold, "increaseCapacityThreshold", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->decreaseCapacityThreshold, "decreaseCapacityThreshold", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->decreaseCapacityDuration, "decreaseCapacityDuration", indent_level + 1);    

        tms::OperatorPriorityPluginSupport_print_data(
            (const tms::OperatorPriority*) &sample->priorityLoadCurtailmentAllowed, "priorityLoadCurtailmentAllowed", indent_level + 1);

        tms::OperatorPriorityPluginSupport_print_data(
            (const tms::OperatorPriority*) &sample->priorityPowerPortSheddingAllowed, "priorityPowerPortSheddingAllowed", indent_level + 1);

    }

