    {

        RTICdrType_printIndent(indent_level);

        if (desc != NULL) {
            RTILogParamString_printPlain("%s:\n", desc);
        } else {
            RTILogParamString_printPlain("\n");
        }

        if (sample == NULL) {
            RTILogParamString_printPlain("NULL\n");
            return;
        }

        if (tms::PowerConnectionSeq_get_contiguous_bufferI(sample) != NULL) {
            RTICdrType_printArray(
                tms::PowerConnectionSeq_get_contiguous_bufferI(sample), 
                (RTICdrUnsignedLong) tms::PowerConnectionSeq_get_length(sample),
                sizeof(tms::PowerConnection),
                (RTICdrTypePrintFunction)tms::PowerConnectionPluginSupport_print_data,
                "", indent_level + 1);
        } else {
            RTICdrType_printPointerArray(
                tms::PowerConnectionSeq_get_discontiguous_bufferI(sample), 
                (RTICdrUnsignedLong) tms::PowerConnectionSeq_get_length(sample),
                (RTICdrTypePrintFunction)tms::PowerConnectionPluginSupport_print_data,
                "", indent_level + 1);
        }

    }

