    ConversionTapInfoPluginSupport_create_data_ex(RTIBool allocate_pointers) 
    {
        ConversionTapInfo *sample = NULL;

        sample = new (std::nothrow) ConversionTapInfo();

        if(sample == NULL) {
            return NULL;
        }

        if (!tms::ConversionTapInfo_initialize_ex(sample,allocate_pointers, RTI_TRUE)) {
            /* Coverity reports a possible uninit_use_in_call that will happen if the
            new fails. But if new fails then sample == null and the method will
            return before reach this point. */
            /* coverity[uninit_use_in_call : FALSE] */
            tms::ConversionTapInfo_finalize_ex(sample, RTI_TRUE);
            delete  sample;
            sample=NULL;
        }

        return sample;
    }

