    void 
    ConversionTapInfoPluginSupport_print_data(
        const ConversionTapInfo *sample,
        const char *desc,
        unsigned int indent_level)
    {

        RTICdrType_printIndent(indent_level);

        if (desc != NULL) {
            RTILogParamString_printPlain("%s:\n", desc);
        } else {
            RTILogParamString_printPlain("\n");
        }

        if (sample == NULL) {
            RTILogParamString_printPlain("NULL\n");
            return;
        }

        RTICdrType_printLong(
            &sample->tapId, "tapId", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->phaseShift, "phaseShift", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->voltageRatio, "voltageRatio", indent_level + 1);    

    }

