    void 
    ReplyPluginSupport_print_data(
        const Reply *sample,
        const char *desc,
        unsigned int indent_level)
    {

        RTICdrType_printIndent(indent_level);

        if (desc != NULL) {
            RTILogParamString_printPlain("%s:\n", desc);
        } else {
            RTILogParamString_printPlain("\n");
        }

        if (sample == NULL) {
            RTILogParamString_printPlain("NULL\n");
            return;
        }

        if (sample->requestingDeviceId==NULL) {
            RTICdrType_printString(
                NULL,"requestingDeviceId", indent_level + 1);
        } else {
            RTICdrType_printString(
                sample->requestingDeviceId,"requestingDeviceId", indent_level + 1);    
        }

        if (sample->targetDeviceId==NULL) {
            RTICdrType_printString(
                NULL,"targetDeviceId", indent_level + 1);
        } else {
            RTICdrType_printString(
                sample->targetDeviceId,"targetDeviceId", indent_level + 1);    
        }

        tms::ConfigIdPluginSupport_print_data(
            (const tms::ConfigId*) &sample->config, "config", indent_level + 1);

        RTICdrType_printLong(
            &sample->portNumber, "portNumber", indent_level + 1);    

        RTICdrType_printUnsignedLongLong(
            &sample->requestSequenceId, "requestSequenceId", indent_level + 1);    

        tms::ReplyStatusPluginSupport_print_data(
            (const tms::ReplyStatus*) &sample->status, "status", indent_level + 1);

    }

