    RTIBool 
    ReplyPlugin_instance_to_key(
        PRESTypePluginEndpointData endpoint_data,
        ReplyKeyHolder *dst, 
        const Reply *src)
    {
        if (endpoint_data) {} /* To avoid warnings */   

        if (!RTICdrType_copyStringEx (
            &dst->requestingDeviceId
            ,
            src->requestingDeviceId, 
            ((tms::Identity_MAXLEN)) + 1,
            RTI_FALSE)){
            return RTI_FALSE;
        }
        if (!RTICdrType_copyStringEx (
            &dst->targetDeviceId
            ,
            src->targetDeviceId, 
            ((tms::Identity_MAXLEN)) + 1,
            RTI_FALSE)){
            return RTI_FALSE;
        }
        return RTI_TRUE;
    }

    RTIBool 
    ReplyPlugin_key_to_instance(
        PRESTypePluginEndpointData endpoint_data,
        Reply *dst, const
        ReplyKeyHolder *src)
    {
        if (endpoint_data) {} /* To avoid warnings */   
        if (!RTICdrType_copyStringEx (
            &dst->requestingDeviceId
            ,
            src->requestingDeviceId, 
            ((tms::Identity_MAXLEN)) + 1,
            RTI_FALSE)){
            return RTI_FALSE;
        }
        if (!RTICdrType_copyStringEx (
            &dst->targetDeviceId
            ,
            src->targetDeviceId, 
            ((tms::Identity_MAXLEN)) + 1,
            RTI_FALSE)){
            return RTI_FALSE;
        }
        return RTI_TRUE;
    }

    RTIBool 
    ReplyPlugin_serialized_sample_to_keyhash(
        PRESTypePluginEndpointData endpoint_data,
        struct RTICdrStream *stream, 
        DDS_KeyHash_t *keyhash,
        RTIBool deserialize_encapsulation,
        void *endpoint_plugin_qos) 
    {   
        Reply * sample = NULL;
        sample = (Reply *)
        PRESTypePluginDefaultEndpointData_getTempSample(endpoint_data);
        if (sample == NULL) {
            return RTI_FALSE;
        }

        if (!PRESTypePlugin_interpretedSerializedSampleToKey(
            endpoint_data,
            sample,
            stream, 
            deserialize_encapsulation, 
            RTI_TRUE,
            endpoint_plugin_qos)) {
            return RTI_FALSE;
        }
        if (!PRESTypePlugin_interpretedInstanceToKeyHash(
            endpoint_data, 
            keyhash, 
            sample,
            RTICdrStream_getEncapsulationKind(stream))) {
            return RTI_FALSE;
        }
        return RTI_TRUE;
    }

