    void 
    EnergyStartStopStatePluginSupport_print_data(
        const EnergyStartStopState *sample,
        const char *desc,
        unsigned int indent_level)
    {

        RTICdrType_printIndent(indent_level);

        if (desc != NULL) {
            RTILogParamString_printPlain("%s:\n", desc);
        } else {
            RTILogParamString_printPlain("\n");
        }

        if (sample == NULL) {
            RTILogParamString_printPlain("NULL\n");
            return;
        }

        if (sample->deviceId==NULL) {
            RTICdrType_printString(
                NULL,"deviceId", indent_level + 1);
        } else {
            RTICdrType_printString(
                sample->deviceId,"deviceId", indent_level + 1);    
        }

        tms::EnergyStartStopLevelPluginSupport_print_data(
            (const tms::EnergyStartStopLevel*) &sample->presentLevel, "presentLevel", indent_level + 1);

        tms::EnergyStartStopLevelPluginSupport_print_data(
            (const tms::EnergyStartStopLevel*) &sample->futureLevel, "futureLevel", indent_level + 1);

        RTICdrType_printBoolean(
            &sample->requestLock, "requestLock", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->elapsedTime, "elapsedTime", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->remainingTime, "remainingTime", indent_level + 1);    

        tms::PowerSwitchReasonPluginSupport_print_data(
            (const tms::PowerSwitchReason*) &sample->presentLevelReason, "presentLevelReason", indent_level + 1);

        if (sample->presentLevelActor==NULL) {
            RTICdrType_printString(
                NULL,"presentLevelActor", indent_level + 1);
        } else {
            RTICdrType_printString(
                sample->presentLevelActor,"presentLevelActor", indent_level + 1);    
        }

        tms::PowerSwitchTransitionCodePluginSupport_print_data(
            (const tms::PowerSwitchTransitionCode*) &sample->futureLevelReason, "futureLevelReason", indent_level + 1);

    }

