        void 
        LoadSharingParametersPluginSupport_print_data(
            const LoadSharingParameters *sample,
            const char *desc,
            unsigned int indent_level)
        {

            RTICdrType_printIndent(indent_level);

            if (desc != NULL) {
                RTILogParamString_printPlain("%s:\n", desc);
            } else {
                RTILogParamString_printPlain("\n");
            }

            if (sample == NULL) {
                RTILogParamString_printPlain("NULL\n");
                return;
            }

            RTICdrType_printLong(
                &sample->portNumber, "portNumber", indent_level + 1);    

            tms::ControlCurvePluginSupport_print_data(
                (const tms::ControlCurve*) &sample->referenceFrequency, "referenceFrequency", indent_level + 1);

            tms::ControlCurvePluginSupport_print_data(
                (const tms::ControlCurve*) &sample->referenceVoltage, "referenceVoltage", indent_level + 1);

            RTICdrType_printFloat(
                &sample->minRealPower, "minRealPower", indent_level + 1);    

            RTICdrType_printFloat(
                &sample->maxRealPower, "maxRealPower", indent_level + 1);    

            RTICdrType_printFloat(
                &sample->minFrequency, "minFrequency", indent_level + 1);    

            RTICdrType_printFloat(
                &sample->maxFrequency, "maxFrequency", indent_level + 1);    

            RTICdrType_printFloat(
                &sample->minReactivePower, "minReactivePower", indent_level + 1);    

            RTICdrType_printFloat(
                &sample->maxReactivePower, "maxReactivePower", indent_level + 1);    

            RTICdrType_printFloat(
                &sample->minVoltage, "minVoltage", indent_level + 1);    

            RTICdrType_printFloat(
                &sample->maxVoltage, "maxVoltage", indent_level + 1);    

        }

