        RTIBool 
        MeasurementUpdatePlugin_instance_to_key(
            PRESTypePluginEndpointData endpoint_data,
            MeasurementUpdateKeyHolder *dst, 
            const MeasurementUpdate *src)
        {
            if (endpoint_data) {} /* To avoid warnings */   

            if (!RTICdrType_copyStringEx (
                &dst->deviceId
                ,
                src->deviceId, 
                ((tms::Identity_MAXLEN)) + 1,
                RTI_FALSE)){
                return RTI_FALSE;
            }
            return RTI_TRUE;
        }

        RTIBool 
        MeasurementUpdatePlugin_key_to_instance(
            PRESTypePluginEndpointData endpoint_data,
            MeasurementUpdate *dst, const
            MeasurementUpdateKeyHolder *src)
        {
            if (endpoint_data) {} /* To avoid warnings */   
            if (!RTICdrType_copyStringEx (
                &dst->deviceId
                ,
                src->deviceId, 
                ((tms::Identity_MAXLEN)) + 1,
                RTI_FALSE)){
                return RTI_FALSE;
            }
            return RTI_TRUE;
        }

        RTIBool 
        MeasurementUpdatePlugin_serialized_sample_to_keyhash(
            PRESTypePluginEndpointData endpoint_data,
            struct RTICdrStream *stream, 
            DDS_KeyHash_t *keyhash,
            RTIBool deserialize_encapsulation,
            void *endpoint_plugin_qos) 
        {   
            MeasurementUpdate * sample = NULL;
            sample = (MeasurementUpdate *)
            PRESTypePluginDefaultEndpointData_getTempSample(endpoint_data);
            if (sample == NULL) {
                return RTI_FALSE;
            }

            if (!PRESTypePlugin_interpretedSerializedSampleToKey(
                endpoint_data,
                sample,
                stream, 
                deserialize_encapsulation, 
                RTI_TRUE,
                endpoint_plugin_qos)) {
                return RTI_FALSE;
            }
            if (!PRESTypePlugin_interpretedInstanceToKeyHash(
                endpoint_data, 
                keyhash, 
                sample,
                RTICdrStream_getEncapsulationKind(stream))) {
                return RTI_FALSE;
            }
            return RTI_TRUE;
        }

