        void 
        LoadSharingStatePluginSupport_print_data(
            const LoadSharingState *sample,
            const char *desc,
            unsigned int indent_level)
        {

            RTICdrType_printIndent(indent_level);

            if (desc != NULL) {
                RTILogParamString_printPlain("%s:\n", desc);
            } else {
                RTILogParamString_printPlain("\n");
            }

            if (sample == NULL) {
                RTILogParamString_printPlain("NULL\n");
                return;
            }

            if (sample->deviceId==NULL) {
                RTICdrType_printString(
                    NULL,"deviceId", indent_level + 1);
            } else {
                RTICdrType_printString(
                    sample->deviceId,"deviceId", indent_level + 1);    
            }

            tms::ConfigIdPluginSupport_print_data(
                (const tms::ConfigId*) &sample->config, "config", indent_level + 1);

            tms::dc::LoadSharingParameterSequencePluginSupport_print_data(
                (const tms::dc::LoadSharingParameterSequence*) &sample->parameters, "parameters", indent_level + 1);

        }

