    void 
    StorageUpdatePluginSupport_print_data(
        const StorageUpdate *sample,
        const char *desc,
        unsigned int indent_level)
    {

        RTICdrType_printIndent(indent_level);

        if (desc != NULL) {
            RTILogParamString_printPlain("%s:\n", desc);
        } else {
            RTILogParamString_printPlain("\n");
        }

        if (sample == NULL) {
            RTILogParamString_printPlain("NULL\n");
            return;
        }

        if (sample->deviceId==NULL) {
            RTICdrType_printString(
                NULL,"deviceId", indent_level + 1);
        } else {
            RTICdrType_printString(
                sample->deviceId,"deviceId", indent_level + 1);    
        }

        RTICdrType_printFloat(
            &sample->internalVoltage, "internalVoltage", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->stateOfCharge, "stateOfCharge", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->availableEnergy, "availableEnergy", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->holdTime, "holdTime", indent_level + 1);    

        tms::Curve2DPluginSupport_print_data(
            (const tms::Curve2D*) &sample->chargeTime, "chargeTime", indent_level + 1);

        tms::Curve2DPluginSupport_print_data(
            (const tms::Curve2D*) &sample->dischargeTime, "dischargeTime", indent_level + 1);

        tms::Curve2DPluginSupport_print_data(
            (const tms::Curve2D*) &sample->maxChargeTime, "maxChargeTime", indent_level + 1);

        tms::Curve2DPluginSupport_print_data(
            (const tms::Curve2D*) &sample->maxDischargeTime, "maxDischargeTime", indent_level + 1);

        RTICdrType_printFloat(
            &sample->maxChargeRate, "maxChargeRate", indent_level + 1);    

        RTICdrType_printFloat(
            &sample->maxDischargeRate, "maxDischargeRate", indent_level + 1);    

    }

