    void 
    DeviceInfoPluginSupport_print_data(
        const DeviceInfo *sample,
        const char *desc,
        unsigned int indent_level)
    {

        RTICdrType_printIndent(indent_level);

        if (desc != NULL) {
            RTILogParamString_printPlain("%s:\n", desc);
        } else {
            RTILogParamString_printPlain("\n");
        }

        if (sample == NULL) {
            RTILogParamString_printPlain("NULL\n");
            return;
        }

        if (sample->deviceId==NULL) {
            RTICdrType_printString(
                NULL,"deviceId", indent_level + 1);
        } else {
            RTICdrType_printString(
                sample->deviceId,"deviceId", indent_level + 1);    
        }

        tms::DeviceRolePluginSupport_print_data(
            (const tms::DeviceRole*) &sample->role, "role", indent_level + 1);

        tms::ProductInfoPluginSupport_print_data(
            (const tms::ProductInfo*) &sample->product, "product", indent_level + 1);

        tms::TopicInfoPluginSupport_print_data(
            (const tms::TopicInfo*) &sample->topics, "topics", indent_level + 1);

        tms::ControlHardwareInfoPluginSupport_print_data(
            (const tms::ControlHardwareInfo*) sample->controlHardware, "controlHardware", indent_level + 1);

        tms::PowerHardwareInfoPluginSupport_print_data(
            (const tms::PowerHardwareInfo*) sample->powerHardware, "powerHardware", indent_level + 1);

        tms::ParameterMetadataSequencePluginSupport_print_data(
            (const tms::ParameterMetadataSequence*) sample->controlParameters, "controlParameters", indent_level + 1);

        tms::ParameterMetadataSequencePluginSupport_print_data(
            (const tms::ParameterMetadataSequence*) sample->metricParameters, "metricParameters", indent_level + 1);

        tms::ControlServiceInfoPluginSupport_print_data(
            (const tms::ControlServiceInfo*) sample->controlService, "controlService", indent_level + 1);

        tms::PowerDeviceInfoPluginSupport_print_data(
            (const tms::PowerDeviceInfo*) sample->powerDevice, "powerDevice", indent_level + 1);

    }

